'use strict';
// UI language layer. Messages live in _locales/<code>/messages.json (chrome.i18n format).
//  - Default: the browser UI language via chrome.i18n.getMessage (synchronous, works everywhere).
//  - Override: the user picks a language in settings. Pages read it synchronously from
//    localStorage so the first paint is already in that language; the service worker loads it
//    from pwm_settings.language. Keys are content hashes generated by tools/i18n-extract.mjs.
globalThis.I18n = (() => {
  const SUPPORTED = ['ja', 'en', 'zh_CN', 'zh_TW', 'ko', 'es', 'pt_BR', 'de', 'fr', 'it'];
  const NAMES = {ja: '日本語', en: 'English', zh_CN: '简体中文', zh_TW: '繁體中文', ko: '한국어', es: 'Español', pt_BR: 'Português (Brasil)', de: 'Deutsch', fr: 'Français', it: 'Italiano'};
  const LS_LOCALE = 'pwm_i18n_locale', LS_MESSAGES = 'pwm_i18n_messages', LS_VERSION = 'pwm_i18n_version';
  const hasLS = (() => { try { return typeof localStorage !== 'undefined' && !!localStorage; } catch { return false; } })();
  const version = () => { try { return chrome.runtime.getManifest().version; } catch { return ''; } };
  let override = null, messages = null;

  function normalize(code) {
    if (!code) return 'en';
    const c = String(code).replace('-', '_');
    if (SUPPORTED.includes(c)) return c;
    const [lang, region] = c.split('_');
    if (lang === 'zh') return /^(TW|HK|MO|Hant)$/i.test(region || '') ? 'zh_TW' : 'zh_CN';
    if (lang === 'pt') return 'pt_BR';
    return SUPPORTED.includes(lang) ? lang : 'en';
  }
  function browserLocale() { try { return normalize(chrome.i18n.getUILanguage()); } catch { return 'en'; } }

  if (hasLS) {
    try {
      const code = localStorage.getItem(LS_LOCALE);
      if (code && SUPPORTED.includes(code) && localStorage.getItem(LS_VERSION) === version()) {
        const parsed = JSON.parse(localStorage.getItem(LS_MESSAGES) || 'null');
        if (parsed && typeof parsed === 'object') { override = code; messages = parsed; }
      }
    } catch { override = null; messages = null; }
  }

  const format = (msg, subs) => msg.replace(/\$(\$|\d)/g, (m, x) => x === '$' ? '$' : (subs?.[Number(x) - 1] ?? ''));
  function t(key, subs) {
    const entry = messages && messages[key];
    if (entry && typeof entry.message === 'string') return format(entry.message, subs);
    let s = '';
    try { s = chrome.i18n.getMessage(key, (subs || []).map(v => String(v))); } catch {}
    return s || key;
  }

  async function load(code) {
    const response = await fetch(chrome.runtime.getURL(`_locales/${code}/messages.json`));
    if (!response.ok) throw Error('locale ' + code);
    return response.json();
  }
  function cache(code, data) {
    if (!hasLS) return;
    try {
      if (!code) { localStorage.removeItem(LS_LOCALE); localStorage.removeItem(LS_MESSAGES); localStorage.removeItem(LS_VERSION); return; }
      localStorage.setItem(LS_LOCALE, code); localStorage.setItem(LS_MESSAGES, JSON.stringify(data)); localStorage.setItem(LS_VERSION, version());
    } catch {}
  }
  async function settingLanguage() {
    try { return ((await chrome.storage.local.get('pwm_settings')).pwm_settings || {}).language || 'auto'; } catch { return 'auto'; }
  }
  // Sync in-memory + localStorage with the stored setting. Returns the effective locale.
  async function ready() {
    const code = await settingLanguage();
    if (code !== 'auto' && SUPPORTED.includes(code)) {
      if (override !== code || !messages) { messages = await load(code); override = code; cache(code, messages); }
    } else if (override || messages) { override = null; messages = null; cache(null); }
    return current();
  }
  async function setLanguage(code) {
    code = code === 'auto' ? 'auto' : normalize(code);
    const cur = ((await chrome.storage.local.get('pwm_settings')).pwm_settings) || {};
    await chrome.storage.local.set({pwm_settings: {...cur, language: code}});
    return ready();
  }
  const current = () => override || browserLocale();

  function apply(root) {
    const scope = root || (typeof document !== 'undefined' ? document : null);
    if (!scope) return;
    scope.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.getAttribute('data-i18n')); });
    scope.querySelectorAll('[data-i18n-attr]').forEach(el => {
      el.getAttribute('data-i18n-attr').split(';').forEach(pair => {
        const i = pair.indexOf(':'); if (i < 0) return;
        el.setAttribute(pair.slice(0, i), t(pair.slice(i + 1)));
      });
    });
    if (scope === document) document.documentElement.lang = current().replace('_', '-');
  }

  return {t, apply, ready, setLanguage, current, normalize, SUPPORTED, NAMES};
})();
globalThis.t = I18n.t;

if (typeof document !== 'undefined') {
  const painted = I18n.current();
  I18n.apply();
  // If the stored setting disagrees with what was painted (first load after changing devices /
  // importing settings), load it once and repaint by reloading. Guarded against loops.
  I18n.ready().then(code => {
    if (code === painted) return;
    try { if (sessionStorage.getItem('pwm_i18n_reloaded') === code) return; sessionStorage.setItem('pwm_i18n_reloaded', code); } catch {}
    location.reload();
  }).catch(() => {});
}
